import math
log=math.log10
def Icorner(m,n):
    # Newmark influence factor for corner of uniformly loaded rectangle
    m2,n2=m*m,n*n
    A=m2+n2+1
    t1=(2*m*n*math.sqrt(A))/(A+m2*n2)*((A+1)/A)
    num=2*m*n*math.sqrt(A); den=A-m2*n2
    t2=math.atan2(num,den)  # handles den<0 branch
    return (t1+t2)/(4*math.pi)
def stress_rect(q, xc, yc, B, L, px, py, z):
    # rectangle centered (xc,yc), size B (x) x L (y); point (px,py) at depth z
    x1,x2 = xc-B/2-px, xc+B/2-px
    y1,y2 = yc-L/2-py, yc+L/2-py
    def F(x,y):
        if x==0 or y==0: return 0.0
        s = (1 if x>0 else -1)*(1 if y>0 else -1)
        return s*Icorner(abs(x)/z, abs(y)/z)
    return q*(F(x2,y2)-F(x1,y2)-F(x2,y1)+F(x1,y1))
# CB-GEO-007 Sheet 2 schedule; 4x3 grid, 26 ft along A-D (x), 24 ft along rows 1-3 (y)
sched = {
 'C1':(0,0,8.5,3590),'C2':(1,0,9.5,3720),'C3':(2,0,9.5,3635),'C4':(3,0,8.5,3495),
 'C5':(0,1,10.5,3650),'C6':(1,1,10.5,3730),'C7':(2,1,10.5,3555),'C8':(3,1,10.5,3450),
 'C9':(0,2,9.5,3660),'C10':(1,2,9.5,3570),'C11':(2,2,8.5,3540),'C12':(3,2,8.5,3480)}
SX,SY=26.0,24.0
def field(px,py,z):
    return sum(stress_rect(q,i*SX,j*SY,B,B,px,py,z) for (i,j,B,q) in sched.values())
Cc=0.28;Cr=0.045;e0=0.92;HR=216/1.92;sp=1900
def sc_nc(s0,ds): return Cc*HR*log((s0+ds)/s0)
def sc_split(s0,ds):
    sf=s0+ds
    return (Cr*HR*log(sp/s0)+Cc*HR*log(sf/sp)) if sf>sp else Cr*HR*log(sf/s0)
print("== CB-GEO-007 geometry, footing base El.740.5, mid-clay El.729.0 (z=11.5 ft) ==")
z=11.5
res={}
for k,(i,j,B,q) in sched.items():
    own = stress_rect(q,i*SX,j*SY,B,B,i*SX,j*SY,z)
    tot = field(i*SX,j*SY,z)
    two = q*B*B/((B+z)**2)
    res[k]=tot
    print(f"{k:4s} B={B:4.1f} q={q}: 2:1 own={two:5.0f}  Bouss own={own:5.0f}  Bouss all={tot:5.0f}  Sc(NC)={sc_nc(1850,tot):4.2f}  Sc(split)={sc_split(1850,tot):4.2f}")
print("bay centres:")
for bi in range(3):
    for bj in range(2):
        px,py=(bi+0.5)*SX,(bj+0.5)*SY
        print(f"  bay ({bi},{bj}) centre: ds = {field(px,py,z):.0f} psf")
mx=max(res.values()); mn=min(res.values())
print(f"range under footings {mn:.0f}-{mx:.0f}")
# adjacent pair differential of consolidation (split) using Bouss all
pos={k:(v[0],v[1]) for k,v in sched.items()}
pairs=[]
for a in sched:
    for b in sched:
        if a<b:
            (ia,ja),(ib,jb)=pos[a],pos[b]
            if abs(ia-ib)+abs(ja-jb)==1:
                d = SX if ia!=ib else SY
                pairs.append((abs(sc_split(1850,res[a])-sc_split(1850,res[b])),a,b,d))
pairs.sort(reverse=True)
for p in pairs[:6]: print(f"  adj pair {p[1]}-{p[2]} ({p[3]:.0f} ft): dSc = {p[0]:.2f} in")
print("\n== Alternative: S-201 Rev.4 Det.3 interior 7.5x7.5 ft, base El.746.0 (z=17 ft), 4,000 psf net ==")
z2=17.0
own=stress_rect(4000,0,0,7.5,7.5,0,0,z2); two=4000*7.5**2/(7.5+z2)**2
print(f"single footing: 2:1 {two:.0f} psf ; Bouss centre {own:.0f} psf -> Sc(NC) {sc_nc(1850,own):.2f} / split {sc_split(1850,own):.2f}; 2:1 -> {sc_nc(1850,two):.2f} / {sc_split(1850,two):.2f}")
# CB-GEO-007 footings but base at El.746.0
print("CB-GEO-007 footing loads with base El.746.0 (z=17):")
for k in ('C6','C12'):
    i,j,B,q=sched[k]
    print(f"  {k}: Bouss all = {field(i*SX,j*SY,17.0):.0f} psf -> Sc(split) {sc_split(1850,field(i*SX,j*SY,17.0)):.2f}")
